// Controlled mission design basis. Scenario inputs never modify these rules.
// Numbers belong to the cited resource boundary and evidence method.
const freeze = value => {
  if (value && typeof value === 'object') {
    Object.values(value).forEach(freeze);
    Object.freeze(value);
  }
  return value;
};

