// Strict thresholds follow the ">" in GOLD, without display rounding.
export function massMargin(basicKg,predictedKg,allowableKg){
  if(![basicKg,predictedKg,allowableKg].every(Number.isFinite)||basicKg<=0||predictedKg<basicKg)return {status:'unassessed',fraction:null,kg:null};
  const kg=allowableKg-predictedKg,fraction=kg/basicKg;
  return {status:fraction>policyValues.massPdrFraction?'meets':'below',fraction,kg,denominator:'basic dry mass'};
}
export function capacityMargin(available,estimated,threshold=policyValues.powerPdrFraction){
  if(![available,estimated,threshold].every(Number.isFinite)||available<=0||estimated<0)return {status:'unassessed',fraction:null};
  const fraction=(available-estimated)/available;
  return {status:fraction>threshold?'meets':'below',fraction,denominator:'available capacity'};
}

export function equipmentMaturity(row){
  return {
    installedMaturity:'Unassessed',
    referenceEvidence:row.evidence,
    heritageApplicability:'New-application assessment required',
    massEstimateMaturity:'Study allocation / parametric estimate',
    hardwareCategory:row.subsystem,
    fabricationStatus:'Preliminary design; no flight article evidence attached',
    mgaFraction:null,
    mgaBasis:'Awaiting item-specific category / maturity assessment under GOLD 1.06',
    evidenceIds:[], owner:row.subsystem+' owner', due:'Subsystem PDR'
  };
}

export function resolveItemGrowth(record){
  const basis=record?.marginEvidence,hasText=value=>typeof value==='string'&&value.trim().length>0;
  const valid=record?.classification==='Hardware'&&Number.isFinite(record.extendedMassKg)&&record.extendedMassKg>=0&&basis?.approved===true&&Number.isFinite(basis.mgaFraction)&&basis.mgaFraction>=0&&hasText(basis.source)&&Array.isArray(basis.evidenceIds)&&basis.evidenceIds.length>0&&basis.evidenceIds.every(hasText)&&[basis.hardwareCategory,basis.designMaturity,basis.fabricationStatus].every(hasText);
  return valid?{status:'assigned',basicKg:record.extendedMassKg,mgaKg:record.extendedMassKg*basis.mgaFraction,basis}:{status:record?.classification==='Hardware'?'unassessed':'outside_dry_hardware',basicKg:record?.extendedMassKg??null,mgaKg:null,basis:null};
}

